const items = $input.all();

return items.map(item => {
  const invoice = item.json.output;
  const errors = [];

  // -------------------------
  // Required fields
  // -------------------------

  if (!invoice.invoice_number?.trim()) {
    errors.push("Missing invoice number");
  }

  if (!invoice.supplier_name?.trim()) {
    errors.push("Missing supplier name");
  }

  if (!invoice.invoice_date) {
    errors.push("Missing invoice date");
  }

  if (!invoice.currency?.trim()) {
    errors.push("Missing currency");
  }

  // -------------------------
  // Monetary values
  // -------------------------

  if (
    invoice.subtotal !== null &&
    invoice.subtotal !== undefined &&
    invoice.subtotal < 0
  ) {
    errors.push("Subtotal cannot be negative");
  }

  if (
    invoice.tax !== null &&
    invoice.tax !== undefined &&
    invoice.tax < 0
  ) {
    errors.push("Tax cannot be negative");
  }

  if (invoice.withholding_tax < 0) {
    errors.push("Withholding tax cannot be negative");
  }

  if (
    invoice.total !== null &&
    invoice.total !== undefined &&
    invoice.total < 0
  ) {
    errors.push("Total cannot be negative");
  }

  // -------------------------
  // Line items
  // -------------------------

  if (!Array.isArray(invoice.line_items) || invoice.line_items.length === 0) {
    errors.push("Invoice has no line items");
  } else {
    for (const [index, lineItem] of invoice.line_items.entries()) {
      const itemNumber = index + 1;

      if (!lineItem.description?.trim()) {
        errors.push(`Line item ${itemNumber}: missing description`);
      }

      if (
        lineItem.quantity === null ||
        lineItem.quantity === undefined ||
        !Number.isFinite(lineItem.quantity)
      ) {
        errors.push(`Line item ${itemNumber}: invalid quantity`);
      } else if (lineItem.quantity <= 0) {
        errors.push(
          `Line item ${itemNumber}: quantity must be greater than 0`
        );
      }

      if (
        lineItem.unit_price === null ||
        lineItem.unit_price === undefined ||
        !Number.isFinite(lineItem.unit_price)
      ) {
        errors.push(`Line item ${itemNumber}: invalid unit price`);
      } else if (lineItem.unit_price < 0) {
        errors.push(
          `Line item ${itemNumber}: unit price cannot be negative`
        );
      }

      if (
        lineItem.amount === null ||
        lineItem.amount === undefined ||
        !Number.isFinite(lineItem.amount)
      ) {
        errors.push(`Line item ${itemNumber}: invalid amount`);
      } else if (lineItem.amount < 0) {
        errors.push(
          `Line item ${itemNumber}: amount cannot be negative`
        );
      }
    }
  }

  // -------------------------
  // Line items → subtotal
  // -------------------------

  if (
    invoice.subtotal !== null &&
    invoice.subtotal !== undefined &&
    Array.isArray(invoice.line_items) &&
    invoice.line_items.length > 0
  ) {
    const lineItemsTotal = invoice.line_items.reduce(
      (sum, item) => sum + item.amount,
      0
    );

    if (Math.abs(lineItemsTotal - invoice.subtotal) > 0.01) {
      errors.push(
        `Line items total does not equal subtotal: ${lineItemsTotal} != ${invoice.subtotal}`
      );
    }
  }

  // -------------------------
  // Subtotal + tax - withholding
  // -------------------------

  if (
    invoice.subtotal !== null &&
    invoice.subtotal !== undefined &&
    invoice.tax !== null &&
    invoice.tax !== undefined &&
    invoice.total !== null &&
    invoice.total !== undefined
  ) {
    const calculatedTotal =
      invoice.subtotal +
      invoice.tax -
      invoice.withholding_tax;

    if (Math.abs(calculatedTotal - invoice.total) > 0.01) {
      errors.push(
        `Subtotal + tax - withholding tax does not equal total: ` +
        `${invoice.subtotal} + ${invoice.tax} - ${invoice.withholding_tax} != ${invoice.total}`
      );
    }
  }

  // -------------------------
  // Final result
  // -------------------------

  return {
    json: {
      ...invoice,
      valid: errors.length === 0,
      validation_errors: errors
    }
  };
});

const candidates = $input.all()
  .map(item => item.json)
  .filter(item =>
    item.id !== undefined &&
    item.name !== undefined &&
    item.similarity_score !== undefined
  );

if (candidates.length === 0) {
  return [{
    json: {
      match_status: "NEW"
    }
  }];
}

const sorted = candidates.sort(
  (a, b) => b.similarity_score - a.similarity_score
);

const best = sorted[0];
const second = sorted[1];

// Exact match is always safe.
if (best.similarity_score === 1) {
  return [{
    json: {
      match_status: "MATCHED",
      supplier_id: best.id,
      supplier_name: best.name,
      similarity_score: best.similarity_score
    }
  }];
}

const MATCH_THRESHOLD = 0.90;
const MIN_SCORE_GAP = 0.10;

if (
  best.similarity_score >= MATCH_THRESHOLD &&
  (!second ||
    best.similarity_score - second.similarity_score >= MIN_SCORE_GAP)
) {
  return [{
    json: {
      match_status: "MATCHED",
      supplier_id: best.id,
      supplier_name: best.name,
      similarity_score: best.similarity_score
    }
  }];
}

return [{
  json: {
    match_status: "AMBIGUOUS",
    candidates: sorted
  }
}];

const supplier = $json;

return {
  json: {
    supplier_id: supplier.supplier_id,
    supplier_name: supplier.supplier_name,
    match_status: supplier.match_status
  }
};

const invoice = $('Create Invoice').first().json;
const source = $('Prepare Valid Invoice').first().json;

return source.line_items.map(item => ({
  json: {
    invoice_id: invoice.id,
    description: item.description,
    quantity: item.quantity,
    unit_price: item.unit_price,
    amount: item.amount
  }
}));

const match = $json;
const invoice = $('Prepare Valid Invoice').first().json;

return {
  json: {
    review_required: true,
    review_reason: "Supplier match is ambiguous",

    supplier_name: invoice.supplier_name,
    invoice_number: invoice.invoice_number,
    invoice_date: invoice.invoice_date,

    candidates: match.candidates
  }
};

const email = $input.first().json;
const attachment = $input.first().binary;

return {
  json: {
    sender: email.from,
    subject: email.subject,
  },
  binary: {
    attachment: attachment ? attachment.attachment_0 : null
  }
}

