parameters.jsCode:
const result = $json.output;

const allowedTypes = [
  "INVOICE",
  "NON-INVOICE"
];

const errors = [];

if (!result || typeof result !== "object") {
  errors.push("Classifier returned no valid output");
}

if (!allowedTypes.includes(result?.file_type)) {
  errors.push(`Invalid file_type: ${result?.file_type}`);
}

if (!Array.isArray(result?.extraction_notes)) {
  errors.push("extraction_notes must be an array");
}

return {
  json: {
    ...result,
    classification_valid: errors.length === 0,
    classification_errors: errors
  }
};
